/**
 * Marks generated by scripts/brand-sync.py (never drawn here):
 *   ChipLogo     the a-c mark's S/M/L braille chips — the biggest that fits
 *   CompactMark  the 2-row "> a-c" lockup
 */
import type { TuiPluginApi } from "@opencode-ai/plugin/tui";
import * as OpenTui from "@opentui/solid";
import { createSignal, onCleanup } from "solid-js";
import { BOLD, C, CHIPS, MARK, WORDMARK, type Run } from "../lib/palette.ts";

export type Size = { rows: number; cols: number };

/**
 * Terminal size as a signal (slots must re-render on resize: `docker exec
 * -it` forwards the real pty size a moment after start, so a size read once
 * at mount is often 80x24). Call inside a component.
 */
export function useSize(api: TuiPluginApi): () => Size {
  const dims = (OpenTui as Record<string, unknown>)["useTerminalDimensions"] as
    | (() => () => { width: number; height: number })
    | undefined;
  if (dims) {
    const d = dims();
    return () => ({ rows: d().height, cols: d().width });
  }
  const r = api.renderer as unknown as Record<string, any>;
  const read = (): Size => ({ rows: r["height"] ?? 40, cols: r["width"] ?? 120 });
  const [size, setSize] = createSignal(read());
  const update = () => setSize(read());
  r["on"]?.call(r, "resize", update);
  onCleanup(() => r["off"]?.call(r, "resize", update));
  return size;
}

/** Rows of [colour-or-role, text] runs; one text node per row, a span per run. */
export function Runs(props: { rows: Run[][]; palette?: Record<string, string> }) {
  const fg = (c: string | null) => (c ? (props.palette?.[c] ?? c) : undefined);
  return (
    <box flexDirection="column" flexShrink={0}>
      {props.rows.map((row) => (
        <text wrapMode="none">
          {row.map(([colour, text]) => (colour ? <span style={{ fg: fg(colour) }}>{text}</span> : text))}
        </text>
      ))}
    </box>
  );
}

/** Rows the home screen needs besides the logo: prompt, tabs, gaps, footer. */
export const HOME_CHROME_ROWS = 10;

export function pickChip(size: Size, chrome = HOME_CHROME_ROWS) {
  return [...CHIPS].reverse().find((c) => c.rows + chrome <= size.rows && c.cols + 4 <= size.cols);
}

export function ChipLogo(props: { api: TuiPluginApi }) {
  const size = useSize(props.api);
  // called inside JSX, so the Solid compiler re-runs it on every resize
  const logo = () => {
    const chip = pickChip(size());
    if (chip) return <Runs rows={chip.lines} />;
    if (MARK && size().rows >= HOME_CHROME_ROWS + 3) return <Runs rows={MARK.compact.rows} palette={MARK.palette} />;
    return <text fg={C.accent} attributes={BOLD}>{WORDMARK}</text>;
  };
  return (
    <box flexDirection="column" alignItems="center" flexShrink={0}>
      {logo()}
    </box>
  );
}

export function CompactMark() {
  return MARK
    ? <Runs rows={MARK.compact.rows} palette={MARK.palette} />
    : <text fg={C.accent} attributes={BOLD}>{WORDMARK}</text>;
}
